import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Instant Answers & Keyword Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/instant-answers.md","filePath":"user-guide/instant-answers.md","lastUpdated":1783846423000}'),s={name:"user-guide/instant-answers.md"};function n(i,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="instant-answers-keyword-shortcuts" tabindex="-1">Instant Answers &amp; Keyword Shortcuts <a class="header-anchor" href="#instant-answers-keyword-shortcuts" aria-label="Permalink to &quot;Instant Answers &amp; Keyword Shortcuts&quot;">​</a></h1><p>Some results appear instantly as you type, without waiting for a file search — either always on, or gated behind a short keyword you type before your actual query (so a large feature like browser history search doesn&#39;t compete for attention on every unrelated keystroke). Most keyword-gated ones have their keyword configured in <strong>Settings → Plugins → Configure</strong>.</p><h2 id="always-on" tabindex="-1">Always on <a class="header-anchor" href="#always-on" aria-label="Permalink to &quot;Always on&quot;">​</a></h2><p>These need no keyword — they activate as soon as what you type matches their pattern.</p><h3 id="calculator" tabindex="-1">Calculator <a class="header-anchor" href="#calculator" aria-label="Permalink to &quot;Calculator&quot;">​</a></h3><p>Type a math expression directly and the result appears live, with <strong>Enter</strong> copying it to the clipboard:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>Explicit base conversion is also supported:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h3><ul><li><code>%NAME%</code> expands a specific variable (including multi-path variables like <code>%PATH%</code>, split into one entry per path).</li><li><code>%partial</code> fuzzy-lists every variable whose name matches <code>partial</code>.</li></ul><h3 id="run-a-command" tabindex="-1">Run a command <a class="header-anchor" href="#run-a-command" aria-label="Permalink to &quot;Run a command&quot;">​</a></h3><ul><li><code>#&lt;command&gt;</code> opens a Command Prompt window and runs <code>&lt;command&gt;</code> <strong>as Administrator</strong>.</li><li><code>$&lt;command&gt;</code> opens a Command Prompt window and runs <code>&lt;command&gt;</code> normally.</li></ul><h3 id="bare-urls" tabindex="-1">Bare URLs <a class="header-anchor" href="#bare-urls" aria-label="Permalink to &quot;Bare URLs&quot;">​</a></h3><p>Type or paste a <code>http://</code>/<code>https://</code> address and SwiftList offers to open it directly.</p><h2 id="keyword-triggered-built-in-configurable-prefix" tabindex="-1">Keyword-triggered (built-in, configurable prefix) <a class="header-anchor" href="#keyword-triggered-built-in-configurable-prefix" aria-label="Permalink to &quot;Keyword-triggered (built-in, configurable prefix)&quot;">​</a></h2><p>Type the keyword, a space, then your query. Each keyword defaults to a short prefix but can be changed independently in that plugin&#39;s own <strong>Configure</strong> dialog if it collides with something you type often.</p><table tabindex="0"><thead><tr><th>Keyword (default)</th><th>Plugin</th><th>What it searches</th></tr></thead><tbody><tr><td><code>ps</code></td><td>Process Manager</td><td>Running processes by name — select one to kill it.</td></tr><tr><td><code>tr</code></td><td>Translation</td><td>Translates the typed text, auto-detecting source language and translating to/from your interface language.</td></tr><tr><td><code>bm</code></td><td>Browser Data</td><td>Bookmarks and history from Chrome/Chromium-family and Firefox-family browser profiles you&#39;ve added under that plugin&#39;s own settings.</td></tr></tbody></table><h2 id="web-search" tabindex="-1">Web search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web search&quot;">​</a></h2><p>Web Search ships with default keywords for several engines/sites — <code>bd</code> (Baidu), <code>g</code> (Google), <code>bing</code> (Bing), <code>gh</code> (GitHub), <code>wiki</code> (Wikipedia), <code>yt</code> (YouTube) — and lets you add, edit, or remove entries entirely, each with its own name, keyword, icon, and URL template, from <strong>Settings → Plugins → Web Search → Configure</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g swiftlist github</span></span></code></pre></div><p>opens a Google search for &quot;swiftlist github&quot; in your browser.</p><h2 id="fully-custom-you-define-the-keyword" tabindex="-1">Fully custom (you define the keyword) <a class="header-anchor" href="#fully-custom-you-define-the-keyword" aria-label="Permalink to &quot;Fully custom (you define the keyword)&quot;">​</a></h2><h3 id="custom-commands" tabindex="-1">Custom Commands <a class="header-anchor" href="#custom-commands" aria-label="Permalink to &quot;Custom Commands&quot;">​</a></h3><p>Define your own <code>&lt;keyword&gt; &lt;args&gt;</code> commands that launch an external program, configured entirely under <strong>Settings → Plugins → Custom Commands → Configure</strong>. The command&#39;s parameter template supports positional placeholders (<code>%s1</code>, <code>%s2</code>, ... for each space-separated argument) and a whole-remainder placeholder (<code>%s</code> for everything typed after the keyword).</p><hr><p>None of the plugins on this page are required — each can be disabled independently under <a href="./settings/plugins.html">Settings → Plugins</a> if you don&#39;t want it competing for keyboard space, and <a href="./search-syntax.html">Search Syntax</a> covers the separate, always-active fuzzy query language used for everything else (files, folders, applications).</p>`,27)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
